function stop3d(){playing=false;if(frameHandle!==null&&typeof cancelAnimationFrame==='function')cancelAnimationFrame(frameHandle);frameHandle=null;if(scene3&&spatialMotion)scene3.querySelector('#scene3-play').textContent='Lire le mouvement';}
